import{_ as t,o as a,c as r,a2 as d}from"./chunks/framework.D7EuCHIT.js";const u=JSON.parse('{"title":"新增播放模式与真实顺序","description":"","frontmatter":{},"headers":[],"relativePath":"plugins/rules.md","filePath":"plugins/rules.md","lastUpdated":1795384748000}'),o={name:"plugins/rules.md"};function s(l,e,i,n,c,h){return a(),r("div",null,[...e[0]||(e[0]=[d('<h1 id="新增播放模式与真实顺序" tabindex="-1">新增播放模式与真实顺序 <a class="header-anchor" href="#新增播放模式与真实顺序" aria-label="Permalink to &quot;新增播放模式与真实顺序&quot;">​</a></h1><p>使用 <code>examples/rules.c</code>，它发布 LyraPlaybackRulesV3、可选 modes 以及一个“记录导航历史”的可调开关。已有四个模式 ID 0..3 保留；自定义模式用 &gt;=4 的稳定 ID。</p><h2 id="声明模式" tabindex="-1">声明模式 <a class="header-anchor" href="#声明模式" aria-label="Permalink to &quot;声明模式&quot;">​</a></h2><p>modes.describe 输出 size、id 和 UTF-8 label。label 容量 128 字节，模式 ID 不能重复。当前默认菜单最多 64 项且可滚动；这属于默认 UI 容量，插件可替换 UI 实现自己的菜单。</p><p><code>sheet.mode</code> 保存模式 ID，不是菜单行号。卸载提供者时回退实际规则，但不删除用户保存 ID。modes 是 size 检查的可选尾字段，旧表不能无条件读取。</p><h2 id="宿主播放模式控件" tabindex="-1">宿主播放模式控件 <a class="header-anchor" href="#宿主播放模式控件" aria-label="Permalink to &quot;宿主播放模式控件&quot;">​</a></h2><p>播放页队列面板的模式菜单与资料库分组的播放菜单读取同一组已注册模式。队列面板显示当前播放模式，资料库菜单用所选模式发起分组播放。两处都按稳定 ID 传递用户选择。</p><table tabindex="0"><thead><tr><th>内置 ID</th><th>模式</th></tr></thead><tbody><tr><td>0</td><td>顺序播放</td></tr><tr><td>1</td><td>列表循环</td></tr><tr><td>2</td><td>单曲循环</td></tr><tr><td>3</td><td>随机播放</td></tr></tbody></table><p>内置标签使用当前语言的宿主文案。插件标签由 <code>modes.describe</code> 返回，必须非空并在固定缓冲内以 NUL 结尾。默认菜单的 64 项上限包含四项内置模式，最多可追加 60 项。菜单字号与间距可查 <a href="/LyraPlayer-docs-site/config/reference/ui-sheet">队列面板配置</a>，配色可查 <a href="/LyraPlayer-docs-site/plugins/theming">主题与组件换肤</a>。</p><p>更换语言、注册插件模式或卸载模式后，应核对播放页和资料库两处的标签与可选项。队列的实际顺序和切歌行为由规则接口决定。</p><h2 id="两个必须一致的函数" tabindex="-1">两个必须一致的函数 <a class="header-anchor" href="#两个必须一致的函数" aria-label="Permalink to &quot;两个必须一致的函数&quot;">​</a></h2><p>next 接收 mode、count、current、delta、automatic 和单调时间熵，返回目录 row 或 -1 停止，以及是否记录历史。order 返回真实队列目录索引和当前队列行。</p><p>只改 next、不改 order，会让播放顺序页显示错误；只改 order、不改 next，会让页面和实际切歌分裂。返回行必须有效，总数不能超过缓冲容量；空目录要安全失败。</p><p>非自定义模式可以委托已查询的默认 rules 接口；不要调用自己的活动接口形成递归。每个模式的手动 previous/next 与自动 EOF 边界应明确定义。</p><h2 id="参数与顺序分离" tabindex="-1">参数与顺序分离 <a class="header-anchor" href="#参数与顺序分离" aria-label="Permalink to &quot;参数与顺序分离&quot;">​</a></h2><p>示例反向列表按每次一首导航，order 按相同反向顺序提供全部歌曲。<code>example.remember_history</code> 只控制返回的 remember 标志，不改变队列顺序，避免参数变化导致 next 与 order 分裂。默认 true；可在配置中改为 false。</p><h2 id="必测场景" tabindex="-1">必测场景 <a class="header-anchor" href="#必测场景" aria-label="Permalink to &quot;必测场景&quot;">​</a></h2><p>空曲库、单首、第一首 previous、最后一首 next、自动 EOF、连续切歌、seek 到末尾、模式切换、目录修改与插件卸载恢复。播放命令不能自动关闭用户正在看的抽屉或歌词页。</p>',18)])])}const m=t(o,[["render",s]]);export{u as __pageData,m as default};
